def solve_tsp(distances: List[List[int]]) -> int:
    import itertools

    def tsp_recursive(current_city: int, visited: set, distances: List[List[int]], cities: int, memo: dict) -> int:
        if len(visited) == cities:
            return distances[current_city][0]

        if (current_city, frozenset(visited)) in memo:
            return memo[(current_city, frozenset(visited))]

        min_cost = float('inf')
        for next_city in range(cities):
            if next_city not in visited:
                visited.add(next_city)
                cost = distances[current_city][next_city] + tsp_recursive(0, visited, distances, cities, memo)
                min_cost = min(min_cost, cost)
                visited.remove(next_city)

        memo[(current_city, frozenset(visited))] = min_cost
        return min_cost

    cities = len(distances)
    memo = {}
    return tsp_recursive(0, {0}, distances, cities, memo)

from typing import List

def solve_tsp(distances: List[List[int]]) -> int:
    import itertools

    def tsp_recursive(current_city: int, visited: set, distances: List[List[int]], cities: set) -> int:
        if len(visited) == len(cities):
            return distances[current_city][0]

        min_cost = float('inf')
        for next_city in cities - visited:
            cost = distances[current_city][next_city] + tsp_recursive(next_city, visited | {next_city}, distances, cities)
            min_cost = min(min_cost, cost)

        return min_cost

    cities = set(range(len(distances)))
    start_city = 0
    visited = {start_city}

    return tsp_recursive(start_city, visited, distances, cities)

