from typing import List

def solve_tsp(distances: List[List[int]]) -> int:
    n = len(distances)
    memo = {}

    def tsp(current_city: int, visited: int, last_visited: int) -> int:
        if visited == (1 << n) - 1:
            return distances[current_city][last_visited]

        if (current_city, visited, last_visited) in memo:
            return memo[(current_city, visited, last_visited)]

        min_cost = float('inf')
        for next_city in range(n):
            if visited & (1 << next_city) == 0:
                new_visited = visited | (1 << next_city)
                cost = distances[current_city][next_city] + tsp(next_city, new_visited, current_city)
                min_cost = min(min_cost, cost)

        memo[(current_city, visited, last_visited)] = min_cost
        return min_cost

    min_cost = float('inf')
    for start_city in range(n):
        cost = distances[start_city][0] + tsp(0, 1 << start_city, 0)
        min_cost = min(min_cost, cost)

    return min_cost
