from itertools import combinations, permutations

def is_arithmetic_progression(a, b, c):
    return sorted([a, b, c]) in [(a, a + d, a + 2 * d) for d in range(1, 15)]

def solve_octagon_prob(numbers):
    def is_right_triangle(a, b, c):
        sides = sorted([a, b, c])
        return sides[2]**2 == sides[0]**2 + sides[1]**2

    count = 0
    total = 0
    for vertices in combinations(numbers, 3):
        a, b, c = vertices
        if is_right_triangle(abs(a - b), abs(b - c), abs(c - a)):
            total += 1
            for perm in permutations(vertices):
                if is_arithmetic_progression(*perm):
                    count += 1
                    break
    return count / total if total else 0

assert solve_octagon_prob(list(range(9, 17))) == 107
assert solve_octagon_prob([1, 2, 3, 4, 5, 6, 7, 8]) == 107
