from itertools import combinations, permutations

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

def lcm_multiple(numbers):
    lcm_value = numbers[0]
    for number in numbers[1:]:
        lcm_value = lcm(lcm_value, number)
    return lcm_value

def solve_octagon_prob(numbers):
    def is_arithmetic_progression(a, b, c):
        return (a + c == 2 * b or
                lcm_multiple([a, b, c]) == lcm(a, lcm(b, c)))

    def is_right_triangle(a, b, c):
        sides = sorted([a, b, c])
        return sides[0]**2 + sides[1]**2 == sides[2]**2

    octagon_combinations = combinations(numbers, 3)
    valid_triangles = 0

    for triangle in octagon_combinations:
        for perm in permutations(triangle):
            if is_arithmetic_progression(*perm) and is_right_triangle(*perm):
                valid_triangles += 1
                break

    total_triangles = 8 * 7 * 6 // 6
    from fractions import Fraction
    probability = Fraction(valid_triangles, total_triangles)
    return probability.numerator + probability.denominator

# Test cases
assert solve_octagon_prob(list(range(9, 17))) == 107
assert solve_octagon_prob([1, 2, 3, 4, 5, 6, 7, 8]) == 107
