from typing import Optional

def calculate_inverse_prob(start: int, end: int) -> Optional[int]:
    if start > end:
        return None

    count = 0
    for num in range(start, end + 1):
        str_num = str(num).zfill(5)
        a1, a2, a3, a4, a5 = map(int, str_num)
        if a1 <= a2 + 1 <= a3 - 7 < a4 <= a5 + 2:
            count += 1

    if count == 0:
        return None
    return round(1 / (count / (end - start + 1)))

