def solve_min_products(fixed_cost: int, variable_cost: int, selling_price: int) -> int:
    def calculate_profit(x: int) -> int:
        total_cost = fixed_cost + variable_cost * x
        revenue = selling_price * x
        if x < 100:
            tax = revenue * 0.1
        elif 100 <= x < 300:
            tax = revenue * 0.08
        else:
            tax = revenue * 0.05
        return revenue - total_cost - tax

    x = 1
    while calculate_profit(x) <= 0:
        x += 1
    return x

