from typing import *

def count_ap_triplets(n: int, max_sum: int) -> int:
    def is_ap(a, b, c):
        return (b - a) == (c - b)

    count = 0
    for i in range(1, n - 1):
        for j in range(i + 1, n):
            k = 2 * j - i
            if k > n:
                break
            if is_ap(i, j, k) and i + j + k <= max_sum:
                count += 1
    return count

