from math import comb

def calculate_win_probability(p: float) -> float:
    if not 0 <= p <= 1:
        raise ValueError("Probability p must be between 0 and 1")

    total_prob = 0
    for i in range(3):
        prob = 0
        for j in range(i, 3):
            prob += comb(2 + j - i, j - i) * (p ** (3 - i)) * ((1 - p) ** j) * comb(5 - j, 2)
        total_prob += prob

    return round(total_prob, 2)

