from math import comb

def calculate_win_probability(p: float) -> float:
    total_probability = 0
    for i in range(3):
        probability = 0
        for j in range(3):
            if i + j >= 5:
                break
            probability += comb(5 - i - j, j) * (p ** (3 + j)) * ((1 - p) ** (2 - j))
        total_probability += probability * (p ** i) * ((1 - p) ** (2 - i))
    return round(total_probability, 2)

