from typing import Union

def calculate_win_probability(p: float) -> Union[float, int]:
    def win_series(p: float, wins: int, losses: int) -> float:
        if wins == 3:
            return 1
        if losses == 3:
            return 0
        return (p * win_series(p, wins + 1, losses) +
                (1 - p) * win_series(p, wins, losses + 1))

    return round(sum(win_series(p, 3 - i, i) for i in range(4)), 2)
