        A_reflected = (A[0], A[1], A[0] - width, A[1], A[0], A[1] - length, A[0] - width, A[1] - length)
        B_reflected = (B[0], B[1], B[0] - width, B[1], B[0], B[1] - length, B[0] - width, B[1] - length)
