    def reflect(A: Tuple[int, int], B: Tuple[int, int], width: int, length: int, height: int) -> Tuple[int, int]:
        A_x, A_y = A
        B_x, B_y = B
        min_dist = float('inf')
        best_reflection = (0, 0)

        for x in [0, width, 2 * width]:
            for y in [0, length, 2 * length, 2 * length + height, 2 * length + 2 * height]:
                dist = distance(A_x, A_y, x, y) + distance(x, y, B_x, B_y)
                if dist < min_dist:
                    min_dist = dist
                    best_reflection = (x, y)

        return best_reflection

    A = (A_x, A_y)
    B = (B_x, B_y)
    reflected_B = reflect(A, B, width, length, height)

    return round(distance(A[0], A[1], reflected_B[0], reflected_B[1]))

