from typing import Tuple

def find_max_profit(coefficients: Tuple[float, ...]) -> int:
    a, b, c, d, e, f = coefficients
    discriminant = (2 * d - b) ** 2 - 4 * (3 * c) * (a * d ** 2 - b * c * d + c * e + f)
    if discriminant < 0:
        return None
    x1 = (-2 * d + b + discriminant ** 0.5) / (6 * c)
    x2 = (-2 * d + b - discriminant ** 0.5) / (6 * c)
    if x1 >= 0 and x2 >= 0:
        return int(max(x1, x2))
    elif x1 >= 0:
        return int(x1)
    elif x2 >= 0:
        return int(x2)
    else:
        return None

def maximize_profit(a: float, b: float, c: float, d: float, e: float, f: float) -> int:
    coefficients = (a, b, c, d, e, f)
    return find_max_profit(coefficients)

