def is_equilateral_triangle(a, b, c, n):
    return (abs(a - b) == 1 and abs(b - c) == 1 and abs(c - a) == 1) or \
           (abs(a - b) == n - 2 and abs(b - c) == n - 2 and abs(c - a) == n - 2)

def count_rotor_arrangements(n, masses):
    if n != 9 or len(masses) != 9:
        raise ValueError("n must be 9 and masses must be a list of 9 distinct integers.")

    total = 0
    for perm in permutations(masses):
        for i in range(n):
            a, b, c = perm[i], perm[(i + 3) % n], perm[(i + 6) % n]
            if a + b + c == sum(masses) // 3 and is_equilateral_triangle(a, b, c, n):
                total += 1
                break
    return total // 6  # Each valid arrangement is counted 6 times due to rotations and reflections

