import numpy as np
from scipy.optimize import minimize_scalar

def g(x):
    return (x + 1) / (x - 2)

def distance_point_to_curve(mx, my):
    def distance_sq(x):
        return (x - mx)**2 + (g(x) - my)**2

    result = minimize_scalar(distance_sq, bounds=(2.001, 10), method='bounded')
    closest_x = result.x
    closest_y = g(closest_x)
    return np.sqrt((mx - closest_x)**2 + (my - closest_y)**2)

def solve_min_distance(mx: float, my: float) -> float:
    distance = distance_point_to_curve(mx, my)
