def solve_max_profit(initial_price=30, initial_orders=60, initial_qty=100, price_step=2, order_dec=4, qty_dec=2, cost_price=24, max_price=50) -> int:
    def profit(price: int) -> float:
        orders = initial_orders - (price - initial_price) // price_step * order_dec
        quantity = initial_qty - (price - initial_price) // price_step * qty_dec
        if orders * quantity <= 0:
            return 0
        return (price - cost_price) * orders * quantity / 1000

    max_profit = 0
    optimal_price = 0
    for price in range(initial_price, max_price + 1, price_step):
        current_profit = profit(price)
        if current_profit > max_profit:
            max_profit = current_profit
            optimal_price = price

    return round(optimal_price)

