from typing import Tuple

def solve_gps_problem(A: Tuple[float, float, float], B: Tuple[float, float, float], C: Tuple[float, float, float], D: Tuple[float, float, float]) -> float:
    def distance(point1: Tuple[float, float, float], point2: Tuple[float, float, float]) -> float:
        return ((point1[0] - point2[0]) ** 2 + (point1[1] - point2[1]) ** 2 + (point1[2] - point2[2]) ** 2) ** 0.5

    def line_equation(A: Tuple[float, float, float], B: Tuple[float, float, float]) -> Tuple[float, float, float, float]:
        x1, y1, z1 = A
        x2, y2, z2 = B
        if x1 == x2:
            return (1, 0, -x1, 0)
        if y1 == y2:
            return (0, 1, -y1, 0)
        if z1 == z2:
            return (0, 0, 1, -z1)
        m = (y2 - y1) / (x2 - x1)
        c = y1 - m * x1
        return (1, m, -1, c)

    AB = line_equation(A, B)
    M = (A[0] + B[0] / 2, A[1] + B[1] / 2, A[2] + B[2] / 2)
    distances = [distance(A, M), distance(B, M), distance(C, M)]
    return sum(distances)

