        ("Red", 1), ("Red", 2), ("Red", 3), ("Red", 4),
        ("Yellow", 1), ("Yellow", 2), ("Yellow", 3), ("Yellow", 4)
    ]

    def is_valid(perm):
        for i in range(8):
            face1 = perm[i]
            face2 = perm[(i + 4) % 8]
            if face1[0] == face2[0] or face1[1] == face2[1]:
                return False
        return True

    valid_permutations = 0
    for perm in permutations(triangles):
        if is_valid(perm):
            valid_permutations += 1

