def calculate_p_scaled(n_slots: int, n_books: int, scale_factor: int) -> float:
    def is_valid_distribution(distribution):
        for i in range(len(distribution) - 1):
            if distribution[i] == 2 and (distribution[i + 1] != 0 or distribution[i - 1] != 0):
                return False
        return True

    valid_distributions = 0

    # Generate all possible distributions of 4 slots with 1 book and 6 slots with 0 or 2 books
    for slots_with_1_book in range(4, 7):
        slots_with_2_books = 10 - slots_with_1_book
        if slots_with_2_books % 2 != 0:
            continue
        slots_with_2_books //= 2

        # Choose 4 slots out of 10 for 1 book
        for slots in combinations(range(n_slots), slots_with_1_book):
            distribution = [0] * n_slots
            for slot in slots:
                distribution[slot] = 1

            # Place 2 books in the remaining slots
            remaining_slots = [i for i in range(n_slots) if distribution[i] == 0]
            for slots in combinations(remaining_slots, slots_with_2_books * 2):
                for i in range(0, len(slots), 2):
                    distribution[slots[i]] = 2
                    distribution[slots[i + 1]] = 2

                if is_valid_distribution(distribution):
                    valid_distributions += 1

    total_distributions = comb(10, 4) * comb(6, 2)
    probability = valid_distributions / total_distributions
    return round(scale_factor * probability, 0)

