from math import comb, factorial

def is_valid_distribution(slots: int, books: int) -> bool:
    if books > 2 * slots or books < slots:
        return False
    if books % 2 != slots % 2:
        return False
    return True

def count_valid_distributions(slots: int, books: int) -> int:
    if not is_valid_distribution(slots, books):
        return 0
    if books == 0:
        return 1
    if books == slots:
        return 1
    if books == 2 * slots:
        return 1
    count = 0
    for i in range(slots):
        if i > 0 and slots - i < books - 2:
            break
        if i < slots - 1 and i + 1 < books - 2:
            continue
        count += count_valid_distributions(slots - i - 2, books - 2)
    return count

def calculate_p(slots: int, books: int) -> float:
    valid_distributions = count_valid_distributions(slots, books)
    total_distributions = factorial(slots + books - 1) // (factorial(books) * factorial(slots - 1))
    return valid_distributions / total_distributions

def calculate_p_scaled(slots: int, books: int, scale: int) -> float:
    p = calculate_p(slots, books)
    return p * scale

