def find_min_first_payment(debt: float, target: float, months: int, decay_ratio: float) -> int:
    def monthly_debt(month: int, payment: float) -> float:
        if month == 1:
            return debt - payment
        else:
            return monthly_debt(month - 1, payment * decay_ratio) - payment * decay_ratio

    def binary_search(left: int, right: int) -> int:
        while left < right:
            mid = (left + right) // 2
            remaining_debt = monthly_debt(months, mid)
            if remaining_debt > debt * (1 - target):
                left = mid + 1
            else:
                right = mid
        return left

    return binary_search(0, debt)

