from typing import Union

def find_min_first_payment(debt: int, target: float, months: int, decay_ratio: float) -> Union[int, float]:
    def next_payment(payment: int, month: int) -> int:
        return max(1, int(payment * decay_ratio))

    low, high = 1, debt
    while low < high:
        mid = (low + high) // 2
        remaining_debt = debt
        current_payment = mid
        for month in range(months):
            remaining_debt -= current_payment
            current_payment = next_payment(current_payment, month)
        if remaining_debt * 100 < target * debt - 1:
            low = mid + 1
        else:
            high = mid
    return low

