def find_min_first_payment(debt: float, target: float, months: int, decay: float) -> int:
    def payment_schedule(payment: float) -> float:
        remaining_debt = debt
        for _ in range(months):
            remaining_debt -= payment
            payment *= decay
        return remaining_debt

    low, high = 0, debt
    while low < high:
        mid = (low + high) // 2
        if payment_schedule(mid) > -debt * target:
            high = mid
        else:
            low = mid + 1
    return int(low)

